import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] inputStrings = scanner.nextLine().split(" ");
        int[] inputs = new int[inputStrings.length];
        for (int i = 0; i < inputStrings.length; i++) {
            inputs[i] = Integer.parseInt(inputStrings[i]);
        }
        Arrays.sort(inputs);
        int a = inputs[0];
        int b = inputs[1];
        int prod = a * b;
        Map<Integer, Integer> conditionsMap = new HashMap<>();
        conditionsMap.put(1, 2 * ((b % 6 > 1) && (b % 6 < 5) ? 1 : 0));
        Map<Integer, Integer> nestedMap = new HashMap<>();
        nestedMap.put(2, 4);
        nestedMap.put(3, 2);
        nestedMap.put(7, 2);
        int conditionValue = nestedMap.getOrDefault(b, 0);
        int result = (~1) & (prod - conditionsMap.getOrDefault(a, 0));
        System.out.println(result);
        scanner.close();
    }
}
